cat > src/lib/postmark.ts <<'EOF'
import { ServerClient } from "postmark";

let client: ServerClient | undefined;

// Server-only. Created lazily so the app builds and runs without a token configured.
export function getPostmark(): ServerClient | undefined {
  const token = process.env.POSTMARK_SERVER_TOKEN;
  if (!token) return undefined;
  client ??= new ServerClient(token);
  return client;
}
EOF
cat > src/lib/email.ts <<'EOF'
import { getPostmark } from "@/lib/postmark";

type Message = { to: string; subject: string; html: string; text: string };

function escapeHtml(s: string): string {
  return s.replace(/[&<>"']/g, (c) => `&#${c.charCodeAt(0)};`);
}

// Never throws: a failed email must not break the request that triggered it.
async function send({ to, subject, html, text }: Message): Promise<boolean> {
  const client = getPostmark();
  const from = process.env.POSTMARK_FROM_EMAIL;
  if (!client || !from) {
    console.warn(`[email] Postmark not configured; skipped "${subject}" to ${to}`);
    return false;
  }
  try {
    await client.sendEmail({
      From: from,
      To: to,
      Subject: subject,
      HtmlBody: html,
      TextBody: text,
      MessageStream: process.env.POSTMARK_MESSAGE_STREAM ?? "outbound",
    });
    return true;
  } catch (err) {
    console.error(`[email] failed to send "${subject}" to ${to}`, err);
    return false;
  }
}

export function sendWelcomeEmail(user: { email: string; name: string }) {
  const name = escapeHtml(user.name);
  return send({
    to: user.email,
    subject: "Welcome to Notely",
    html: `<p>Hi ${name},</p><p>Welcome to Notely! Your account is ready.</p>`,
    text: `Hi ${user.name},\n\nWelcome to Notely! Your account is ready.`,
  });
}

export function sendPasswordResetEmail(
  user: { email: string; name: string },
  resetUrl: string,
) {
  const name = escapeHtml(user.name);
  const url = escapeHtml(resetUrl);
  return send({
    to: user.email,
    subject: "Reset your Notely password",
    html: `<p>Hi ${name},</p><p><a href="${url}">Reset your password</a>. The link expires in 1 hour.</p><p>If you didn't ask for this, ignore this email.</p>`,
    text: `Hi ${user.name},\n\nReset your password: ${resetUrl}\nThe link expires in 1 hour.\n\nIf you didn't ask for this, ignore this email.`,
  });
}
EOF
cat > .env.example <<'EOF'
# Postmark (https://postmark.com) — Servers → API Tokens
POSTMARK_SERVER_TOKEN=server_token_placeholder
# Must be a confirmed sender signature or on a verified domain
POSTMARK_FROM_EMAIL=hello@example.com
# Optional, defaults to "outbound"
POSTMARK_MESSAGE_STREAM=outbound
# Base URL used in password reset links
APP_URL=http://localhost:3000
EOF
printf '!.env.example\n' >> .gitignore
python3 - <<'EOF'
p="src/lib/users.ts"
s=open(p).read()
s='import { randomBytes, createHash } from "node:crypto";\nimport { sendPasswordResetEmail, sendWelcomeEmail } from "@/lib/email";\n\n'+s
s+='''
export async function createUser(input: { email: string; name: string }): Promise<User> {
  const email = input.email.trim().toLowerCase();
  if (users.some((u) => u.email === email)) {
    throw new Error("A user with this email already exists");
  }
  const user: User = {
    id: String(users.length + 1),
    email,
    name: input.name.trim(),
    createdAt: new Date().toISOString().slice(0, 10),
  };
  users.push(user);
  await sendWelcomeEmail(user);
  return user;
}

const RESET_TTL_MS = 60 * 60 * 1000;
// token hash -> reset request. In-memory like the user list; move to the DB with real storage.
const resetTokens = new Map<string, { userId: string; expiresAt: number }>();

const hashToken = (token: string) => createHash("sha256").update(token).digest("hex");

// Always resolves the same way whether or not the email exists, so callers can't enumerate users.
export async function requestPasswordReset(email: string): Promise<void> {
  const normalized = email.trim().toLowerCase();
  const user = users.find((u) => u.email === normalized);
  if (!user) return;
  const token = randomBytes(32).toString("hex");
  resetTokens.set(hashToken(token), { userId: user.id, expiresAt: Date.now() + RESET_TTL_MS });
  const base = process.env.APP_URL ?? "http://localhost:3000";
  await sendPasswordResetEmail(user, `${base}/reset-password?token=${token}`);
}

// Validates and consumes a reset token; returns the user it belongs to.
// TODO: no password storage exists yet — the caller must set the new password.
export async function consumePasswordResetToken(token: string): Promise<User | undefined> {
  const key = hashToken(token);
  const entry = resetTokens.get(key);
  resetTokens.delete(key);
  if (!entry || entry.expiresAt < Date.now()) return undefined;
  return getUser(entry.userId);
}
'''
open(p,"w").write(s)
EOF
